public.finora_guard_phase5_posted_record.definition:
CREATE OR REPLACE FUNCTION public.finora_guard_phase5_posted_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.collection not in ('stockMovements','inventoryCounts','assetDepreciations') or coalesce(old.data->>'status','') <> 'posted' then
    return case when tg_op='DELETE' then old else new end;
  end if;
  if tg_op='UPDATE' and new.data=old.data then return new; end if;
  raise exception 'posted Phase 5 operational record is immutable';
end $function$

public.admin_set_license(target uuid, ne.definition:
CREATE OR REPLACE FUNCTION public.admin_set_license(target uuid, new_plan text, days integer DEFAULT NULL::integer, new_status text DEFAULT 'active'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d int;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if new_plan not in ('trial','monthly','three_months','annual','lifetime') then raise exception 'invalid plan'; end if;
  d := coalesce(days, case new_plan when 'trial' then 15 when 'monthly' then 30 when 'three_months' then 90 when 'annual' then 365 else 0 end);
  update public.licenses
     set plan = new_plan,
         status = new_status,
         starts_at = current_date,
         ends_at = case when new_plan = 'lifetime' then date '2099-01-01' else current_date + d end,
         updated_at = now()
   where user_id = target;
  if not found then raise exception 'user not found'; end if;
end $function$

public.finora_guard_posted_journal().definition:
CREATE OR REPLACE FUNCTION public.finora_guard_posted_journal()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  old_status text := old.data->>'status';
  new_status text;
begin
  if old.collection <> 'journalVouchers' or old_status not in ('posted','reversed') then
    return case when tg_op='DELETE' then old else new end;
  end if;
  if tg_op='DELETE' then raise exception 'posted/reversed journal voucher is immutable'; end if;
  new_status := new.data->>'status';
  if old_status='posted' and new_status='reversed'
     and (old.data - array['status','reversalVoucherId','reversedAt']) =
         (new.data - array['status','reversalVoucherId','reversedAt'])
     and coalesce(new.data->>'reversalVoucherId','') <> '' then
    return new;
  end if;
  if new.data = old.data then return new; end if;
  raise exception 'posted/reversed journal voucher is immutable';
end $function$

public.finora_guard_posted_journal_child.definition:
CREATE OR REPLACE FUNCTION public.finora_guard_posted_journal_children()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare vid text; parent_status text;
begin
  if old.collection not in ('journalLines','journalLineDimensions') then return case when tg_op='DELETE' then old else new end; end if;
  vid := old.data->>'voucherId';
  select r.data->>'status' into parent_status
  from public.records r
  where r.owner_id=old.owner_id and r.collection='journalVouchers' and r.id=vid;
  if parent_status in ('posted','reversed') then raise exception 'posted/reversed journal lines are immutable'; end if;
  return case when tg_op='DELETE' then old else new end;
end $function$

public.finora_enforce_company_license_li.definition:
CREATE OR REPLACE FUNCTION public.finora_enforce_company_license_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allowed_count integer; actual_count integer;
begin
  if new.collection<>'companies' then return new; end if;

  select l.max_companies into allowed_count
  from public.licenses l
  where l.organization_id=new.organization_id
  for update;

  if allowed_count is null then raise exception 'organization license not found' using errcode='23503'; end if;

  select count(*)::integer into actual_count
  from public.records r
  where r.organization_id=new.organization_id and r.collection='companies';

  if actual_count>allowed_count then
    raise exception 'company license limit exceeded' using errcode='23514';
  end if;
  return new;
end $function$

public.admin_set_license_modules(target.definition:
CREATE OR REPLACE FUNCTION public.admin_set_license_modules(target uuid, new_modules text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare normalized text[];
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if new_modules is null or cardinality(new_modules)=0 then raise exception 'at least one module is required'; end if;
  if exists (select 1 from unnest(new_modules) m where not private.is_valid_finora_module(m)) then
    raise exception 'invalid module entitlement';
  end if;
  if 'full_suite' = any(new_modules) then normalized := array['full_suite']::text[];
  else select array_agg(distinct m order by m) into normalized from unnest(new_modules) m;
  end if;
  update public.licenses set modules=normalized, updated_at=now() where user_id=target;
  if not found then raise exception 'user not found'; end if;
end
$function$

public.finora_guard_posted_source_record.definition:
CREATE OR REPLACE FUNCTION public.finora_guard_posted_source_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare vid text:=coalesce(old.data->>'journalVoucherId',''); voucher_status text:=''; source_locked boolean:=false;
begin
 if old.collection not in ('invoices','purchases','payments','expenses','cheques','contractStatements','payrollRuns','employeeBenefitAccruals','pettyCashTransactions') then return case when tg_op='DELETE' then old else new end; end if;
 if vid<>'' then select coalesce(r.data->>'status','') into voucher_status from public.records r where r.owner_id=old.owner_id and r.collection='journalVouchers' and r.id=vid; end if;
 source_locked:=coalesce(old.data->>'accountingStatus','')='posted' or (old.collection='cheques' and coalesce(old.data->>'status','') in ('cleared','bounced','cancelled')) or (old.collection='contractStatements' and coalesce(old.data->>'status','') in ('posted','reversed')) or (old.collection in ('payrollRuns','employeeBenefitAccruals','pettyCashTransactions') and coalesce(old.data->>'status','') in ('posted','reversed')) or voucher_status in ('posted','reversed');
 if not source_locked then return case when tg_op='DELETE' then old else new end; end if;
 if tg_op='UPDATE' and new.data=old.data then return new; end if;
 raise exception 'source record linked to posted/reversed accounting history is immutable';
end $function$

public.office_register_correspondence(p_.definition:
CREATE OR REPLACE FUNCTION public.office_register_correspondence(p_id text, p_registry_id text, p_payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  registry_row public.records%rowtype;
  next_no integer;
  prefix text;
  assigned text;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not public.has_active_license() or not private.has_module_entitlement('office_automation') then
    raise exception 'office automation entitlement required' using errcode='42501';
  end if;
  if p_id is null or p_id !~ '^[A-Za-z0-9_-]{1,64}$' then raise exception 'invalid correspondence id'; end if;
  if p_registry_id is null or p_registry_id !~ '^[A-Za-z0-9_-]{1,64}$' then raise exception 'invalid registry id'; end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then raise exception 'invalid payload'; end if;

  select * into registry_row
  from public.records
  where owner_id=auth.uid() and collection='officeRegistries' and id=p_registry_id
  for update;
  if not found then raise exception 'registry not found'; end if;

  next_no := greatest(1,coalesce(nullif(registry_row.data->>'nextNumber','')::integer,1));
  prefix := trim(coalesce(registry_row.data->>'prefix',''));
  assigned := case when prefix='' then next_no::text else prefix||'-'||next_no::text end;

  update public.records
  set data=jsonb_set(registry_row.data,'{nextNumber}',to_jsonb(next_no+1),true)
  where owner_id=auth.uid() and collection='officeRegistries' and id=p_registry_id;

  insert into public.records(owner_id,collection,id,data)
  values(auth.uid(),'correspondence',p_id,
    p_payload || jsonb_build_object(
      'registryId',p_registry_id,
      'registerNumber',assigned,
      'status','registered',
      'registeredAt',now()
    ))
  on conflict(owner_id,collection,id) do update
  set data = case
    when public.records.data->>'status'='registered' then public.records.data
    else excluded.data
  end;

  return assigned;
end
$function$

public.finora_sync_records(p_upserts jso.definition:
CREATE OR REPLACE FUNCTION public.finora_sync_records(p_upserts jsonb DEFAULT '[]'::jsonb, p_deletes jsonb DEFAULT '[]'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not public.has_active_license() then raise exception 'active license required'; end if;
  if exists (
    select 1 from jsonb_to_recordset(coalesce(p_upserts,'[]'::jsonb)) as x(collection text,id text,data jsonb)
    where not private.has_collection_entitlement(x.collection)
  ) or exists (
    select 1 from jsonb_to_recordset(coalesce(p_deletes,'[]'::jsonb)) as d(collection text,id text)
    where not private.has_collection_entitlement(d.collection)
  ) then raise exception 'module entitlement required' using errcode='42501'; end if;

  insert into public.records(owner_id, collection, id, data)
  select auth.uid(), x.collection, x.id, x.data
  from jsonb_to_recordset(coalesce(p_upserts,'[]'::jsonb)) as x(collection text,id text,data jsonb)
  on conflict (owner_id,collection,id) do update set data=excluded.data;

  delete from public.records r
  using jsonb_to_recordset(coalesce(p_deletes,'[]'::jsonb)) as d(collection text,id text)
  where r.owner_id=auth.uid() and r.collection=d.collection and r.id=d.id;
end $function$

private.enforce_organization_member_seat.definition:
CREATE OR REPLACE FUNCTION private.enforce_organization_member_seat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_limit integer; v_active integer;
begin
  if new.status<>'active' then return new; end if;
  if tg_op='UPDATE' and old.status='active' and old.organization_id=new.organization_id then return new; end if;

  select l.max_users into v_limit
  from public.licenses l
  where l.organization_id=new.organization_id
  for update;

  if v_limit is null then
    raise exception 'organization license not found' using errcode='23503';
  end if;

  select count(*)::integer into v_active
  from public.organization_members m
  where m.organization_id=new.organization_id
    and m.status='active'
    and (tg_op='INSERT' or m.id<>new.id);

  if v_active >= v_limit then
    raise exception 'named-user seat limit exceeded' using errcode='23514';
  end if;
  return new;
end $function$

public.admin_set_user_limit(target uuid,.definition:
CREATE OR REPLACE FUNCTION public.admin_set_user_limit(target uuid, new_max_users integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_org uuid; v_active integer;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode='42501'; end if;
  if new_max_users is null or new_max_users<1 or new_max_users>100000 then raise exception 'invalid user limit'; end if;

  select l.organization_id into v_org
  from public.licenses l where l.user_id=target
  for update;
  if v_org is null then raise exception 'user/license not found'; end if;

  select count(*)::integer into v_active
  from public.organization_members m
  where m.organization_id=v_org and m.status='active';

  if new_max_users<v_active then raise exception 'user limit below active member count'; end if;

  update public.licenses
  set max_users=new_max_users,updated_at=now()
  where user_id=target;
end $function$

public.finora_sync_records(p_upserts jso.definition:
CREATE OR REPLACE FUNCTION public.finora_sync_records(p_upserts jsonb DEFAULT '[]'::jsonb, p_deletes jsonb DEFAULT '[]'::jsonb, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_org uuid:=coalesce(p_organization_id,private.default_organization_id());
begin
  if (select auth.uid()) is null then raise exception 'authentication required'; end if;
  if v_org is null or v_org not in (select private.current_organization_ids()) then raise exception 'organization membership required' using errcode='42501'; end if;
  if not private.organization_has_module_entitlement(v_org,'core',true) then raise exception 'active license required' using errcode='42501'; end if;
  if exists(select 1 from jsonb_to_recordset(coalesce(p_upserts,'[]'::jsonb)) as x(collection text,id text,data jsonb) where not private.organization_has_module_entitlement(v_org,private.collection_module(x.collection),true)) or exists(select 1 from jsonb_to_recordset(coalesce(p_deletes,'[]'::jsonb)) as d(collection text,id text) where not private.organization_has_module_entitlement(v_org,private.collection_module(d.collection),true)) then raise exception 'module entitlement required' using errcode='42501'; end if;
  insert into public.records(organization_id,owner_id,collection,id,data) select v_org,(select auth.uid()),x.collection,x.id,x.data from jsonb_to_recordset(coalesce(p_upserts,'[]'::jsonb)) as x(collection text,id text,data jsonb) on conflict (organization_id,collection,id) do update set data=excluded.data;
  delete from public.records r using jsonb_to_recordset(coalesce(p_deletes,'[]'::jsonb)) as d(collection text,id text) where r.organization_id=v_org and r.collection=d.collection and r.id=d.id;
end $function$

private.organization_audit_capture().definition:
CREATE OR REPLACE FUNCTION private.organization_audit_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_org uuid; v_action text; v_entity text; v_entity_id text;
begin
  if tg_table_name='member_module_permissions' then
    v_org:=case when tg_op='DELETE' then old.organization_id else new.organization_id end;
    v_action:='permission_'||lower(tg_op);
    v_entity:='member_module_permission';
    v_entity_id:=case when tg_op='DELETE' then old.id::text else new.id::text end;
  elsif tg_table_name='organization_members' then
    v_org:=case when tg_op='DELETE' then old.organization_id else new.organization_id end;
    v_action:='membership_'||lower(tg_op);
    v_entity:='organization_member';
    v_entity_id:=case when tg_op='DELETE' then old.id::text else new.id::text end;
  elsif tg_table_name='records' then
    v_org:=new.organization_id;
    v_action:='referral_insert';
    v_entity:='correspondence_referral';
    v_entity_id:=new.id;
  else
    if tg_op='DELETE' then return old; else return new; end if;
  end if;

  insert into public.organization_audit(
    organization_id,actor_user_id,action,entity_type,entity_id,before_data,after_data
  )
  values(
    v_org,(select auth.uid()),v_action,v_entity,v_entity_id,
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end
  );

  if tg_op='DELETE' then return old; else return new; end if;
end $function$

